package render_test

import (
	"os"
	"testing"

	"github.com/ashutoshm97/curly-engine/internal/content"
	"github.com/ashutoshm97/curly-engine/internal/layout"
	"github.com/ashutoshm97/curly-engine/internal/normalize"
	"github.com/ashutoshm97/curly-engine/internal/ooxml"
	"github.com/ashutoshm97/curly-engine/internal/render"
	"github.com/ashutoshm97/curly-engine/internal/scene"
)

// TestPPTXRoundTrip writes a deck and re-extracts it: the generated file must
// carry the source theme (colors, fonts) and table style.
func TestPPTXRoundTrip(t *testing.T) {
	src, _ := os.ReadFile("../../testdata/acme.pptx")
	rd, err := ooxml.Extract(src, ooxml.DefaultLimits)
	if err != nil {
		t.Fatal(err)
	}
	p, err := normalize.Build(rd, normalize.Options{ID: "acme"})
	if err != nil {
		t.Fatal(err)
	}
	cs := []content.Slide{
		{Layout: "L1", Title: "Round trip", Subtitle: "Generated by curly-engine"},
		{Layout: "L2", Title: "Points", Bullets: []string{"One", "Two & three", "<four>"}},
		{Layout: "L3", Title: "Numbers", Items: []content.Item{{Value: "1", Label: "a"}, {Value: "2", Label: "b"}}},
		{Layout: "L4", Title: "Table", Table: &content.Table{Header: []string{"A", "B"}, Rows: [][]string{{"1", "2"}, {"3", "4"}}}},
	}
	d := &scene.Deck{Title: "RT", WidthPt: p.WidthPt, HeightPt: p.HeightPt}
	for i, c := range cs {
		d.Slides = append(d.Slides, layout.Compose(p, c, i+1))
	}
	out, err := render.PPTX(d, p, func(ref string) ([]byte, error) { return rd.Assets[ref].Data, nil })
	if err != nil {
		t.Fatal(err)
	}
	if os.Getenv("DUMP") != "" {
		os.WriteFile("/tmp/roundtrip.pptx", out, 0o644)
	}
	back, err := ooxml.Extract(out, ooxml.DefaultLimits)
	if err != nil {
		t.Fatalf("re-extract: %v", err)
	}
	if len(back.Slides) != 4 {
		t.Fatalf("slides = %d", len(back.Slides))
	}
	p2, err := normalize.Build(back, normalize.Options{ID: "rt"})
	if err != nil {
		t.Fatal(err)
	}
	if p2.Color("accent1") != p.Color("accent1") || p2.Font("heading").Family != p.Font("heading").Family {
		t.Errorf("theme lost: accent1 %s vs %s, heading %s vs %s", p2.Color("accent1"), p.Color("accent1"), p2.Font("heading").Family, p.Font("heading").Family)
	}
	if len(p2.Tables) == 0 || p2.Tables[0].Header.Fill == "" {
		t.Errorf("table style lost: %+v", p2.Tables)
	}
}
